let _markdown = "\n\nOverview [#overview]\n\n<FeedbackBlock id=\"5258739d99a05da2\" body=\"For the setup guide, see Integrate Algolia Search.\">\n  For the setup guide, see [Integrate Algolia Search](/docs/headless/search/algolia).\n</FeedbackBlock>\n\n<FeedbackBlock\n  id=\"9ddf1798306af6c3\"\n  body=\"While generally we recommend building your own search with their client-side\nSDK, you can also plug the built-in dialog interface.\"\n>\n  While generally we recommend building your own search with their client-side\n  SDK, you can also plug the built-in dialog interface.\n</FeedbackBlock>\n\nSetup [#setup]\n\n<FeedbackBlock id=\"5bdefd0d218cc914\" body=\"Create a search dialog, replace appId, apiKey and indexName with your desired values.\">\n  Create a search dialog, replace `appId`, `apiKey` and `indexName` with your desired values.\n</FeedbackBlock>\n\n```tsx title=\"components/search.tsx\"\n'use client';\nimport { liteClient } from 'algoliasearch/lite';\nimport {\n  SearchDialog,\n  SearchDialogClose,\n  SearchDialogContent,\n  SearchDialogFooter,\n  SearchDialogHeader,\n  SearchDialogIcon,\n  SearchDialogInput,\n  SearchDialogList,\n  SearchDialogOverlay,\n  type SharedProps,\n} from 'fumadocs-ui/components/dialog/search';\nimport { useDocsSearch } from 'fumadocs-core/search/client';\nimport { useI18n } from 'fumadocs-ui/contexts/i18n';\n\nconst appId = 'replace me';\nconst apiKey = 'replace me';\nconst client = liteClient(appId, apiKey);\n\nexport default function CustomSearchDialog(props: SharedProps) {\n  const { locale } = useI18n(); // (optional) for i18n\n  const { search, setSearch, query } = useDocsSearch({\n    type: 'algolia',\n    client,\n    indexName: 'document',\n    locale,\n  });\n\n  return (\n    <SearchDialog search={search} onSearchChange={setSearch} isLoading={query.isLoading} {...props}>\n      <SearchDialogOverlay />\n      <SearchDialogContent>\n        <SearchDialogHeader>\n          <SearchDialogIcon />\n          <SearchDialogInput />\n          <SearchDialogClose />\n        </SearchDialogHeader>\n        <SearchDialogList items={query.data !== 'empty' ? query.data : null} />\n        <SearchDialogFooter>\n          <a\n            href=\"https://algolia.com\"\n            rel=\"noreferrer noopener\"\n            className=\"ms-auto text-xs text-fd-muted-foreground\"\n          >\n            Search powered by Algolia\n          </a>\n        </SearchDialogFooter>\n      </SearchDialogContent>\n    </SearchDialog>\n  );\n}\n\n```\n\n<Callout title=\"Note\" className=\"mt-4\">\n  `useDocsSearch()` doesn't use instant search (their official\n  Javascript client).\n</Callout>\n\nReplace Search Dialog [#replace-search-dialog]\n\n<FeedbackBlock id=\"0176c4209b9d8310\" body=\"Replace the search dialog with yours from <RootProvider />:\">\n  Replace the search dialog with yours from [`<RootProvider />`](/docs/ui/root-provider):\n</FeedbackBlock>\n\n```tsx\nimport { RootProvider } from 'fumadocs-ui/provider/<framework>';\n// [!code ++]\nimport SearchDialog from '@/components/search';\n\n<RootProvider\n  // [!code ++:3]\n  search={{\n    SearchDialog,\n  }}\n>\n  {children}\n</RootProvider>;\n```\n\n<FeedbackBlock id=\"37fcb4c8b8394fab\" body=\"If it was in a server component, you would need a separate client component for provider to pass functions:\">\n  If it was in a server component, you would need a separate client component for provider to pass functions:\n</FeedbackBlock>\n\n<CodeBlockTabs defaultValue=\"provider.tsx\">\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"provider.tsx\">\n      provider.tsx\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"app/layout.tsx\">\n      app/layout.tsx\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"provider.tsx\">\n    ```tsx\n    'use client';\n    import { RootProvider } from 'fumadocs-ui/provider/<framework>';\n    import SearchDialog from '@/components/search';\n    import type { ReactNode } from 'react';\n\n    export function Provider({ children }: { children: ReactNode }) {\n      return (\n        <RootProvider\n          search={{\n            SearchDialog,\n          }}\n        >\n          {children}\n        </RootProvider>\n      );\n    }\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"app/layout.tsx\">\n    ```tsx\n    import { Provider } from './provider';\n    import type { ReactNode } from 'react';\n\n    export default function Layout({ children }: { children: ReactNode }) {\n      return (\n        <html lang=\"en\">\n          <body>\n            <RootProvider>{children}</RootProvider>\n            <Provider>{children}</Provider>\n          </body>\n        </html>\n      );\n    }\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\nTag Filter [#tag-filter]\n\n<FeedbackBlock id=\"8ddb9a20e77716a0\" body=\"Optionally, you can add UI for filtering results by tags. Configure Tag Filter on search server and add the following:\">\n  Optionally, you can add UI for filtering results by tags. Configure [Tag Filter](/docs/headless/search/algolia#tag-filter) on search server and add the following:\n</FeedbackBlock>\n\n```tsx\n'use client';\n\nimport {\n  SearchDialog,\n  SearchDialogContent,\n  SearchDialogFooter,\n  SearchDialogOverlay,\n  type SharedProps,\n  TagsList,\n  TagsListItem,\n} from 'fumadocs-ui/components/dialog/search';\nimport { useState } from 'react';\nimport { useDocsSearch } from 'fumadocs-core/search/client';\n\nexport default function CustomSearchDialog(props: SharedProps) {\n  // [!code ++]\n  const [tag, setTag] = useState<string | undefined>();\n  const { search, setSearch, query } = useDocsSearch({\n    tag, // [!code ++]\n    // other options depending on your search engine\n  });\n\n  return (\n    <SearchDialog>\n      <SearchDialogOverlay />\n      <SearchDialogContent>\n        ...\n        <SearchDialogFooter className=\"flex flex-row\">\n          <TagsList tag={tag} onTagChange={setTag}>\n            <TagsListItem value=\"my-value\">My Value</TagsListItem>\n          </TagsList>\n        </SearchDialogFooter>\n      </SearchDialogContent>\n    </SearchDialog>\n  );\n}\n```\n";
